        private void CheckForUnionMemberErrors(BindingDiagnosticBag diagnostics)
        {
            Debug.Assert(declaration.Kind is DeclarationKind.Union);

            foreach (var member in GetMembersAndInitializers().NonTypeMembers)
            {
                if (member.IsStatic)
                {
                    continue;
                }

                switch (member)
                {
                    case SourceMemberFieldSymbol field:
                        // Instance fields are not permitted in a union declaration.
                        diagnostics.Add(ErrorCode.ERR_InstanceFieldInUnion, field.GetFirstLocation());
                        break;

                    case SourcePropertySymbolBase { IsAutoPropertyOrUsesFieldKeyword: true } property:
                        // Auto-properties (including those that use the 'field' keyword) require a backing field.
                        diagnostics.Add(ErrorCode.ERR_InstanceFieldInUnion, property.GetFirstLocation());
                        break;

                    case SourceEventSymbol { HasAssociatedField: true } @event:
                        // Field-like events require a backing field.
                        diagnostics.Add(ErrorCode.ERR_InstanceFieldInUnion, @event.GetFirstLocation());
                        break;

                    case SourceConstructorSymbol ctor:
                        if (ctor.ParameterCount == 1)
                        {
                            diagnostics.Add(ErrorCode.ERR_InstanceCtorWithOneParameterInUnion, ctor.GetFirstLocation());
                        }

                        var ctorSyntax = ctor.GetSyntax();
                        var initializer = ctorSyntax.Initializer;
                        if (initializer is null)
                        {
                            // No 'this' initializer at all.
                            diagnostics.Add(ErrorCode.ERR_UnionConstructorCallsDefaultConstructor, ctorSyntax.Identifier.GetLocation());
                        }
                        else if (initializer.Kind() == SyntaxKind.ThisConstructorInitializer &&
                                 initializer.ArgumentList.Arguments.Count == 0)
                        {
                            // A 'this()' initializer that calls the default parameterless constructor.
                            diagnostics.Add(ErrorCode.ERR_UnionConstructorCallsDefaultConstructor, initializer.ThisOrBaseKeyword.GetLocation());
                        }

                        break;
                }
            }
